<?php
namespace App\Domain\AI\Cost;
use App\Domain\AI\Cost\Models\{AiCostBudget,AiCostLedger,AiProviderRate};use App\Domain\AI\Runtime\Models\RuntimeRun;use App\Domain\Network\Tenancy\Models\Tenant;use Illuminate\Support\Facades\DB;use RuntimeException;
final class AiCostGuard {
 public function reserve(Tenant $tenant, RuntimeRun $run): void {if($run->execution_mode?->value!=='live')return; $budget=AiCostBudget::where('tenant_id',$tenant->id)->where('period',now()->format('Y-m'))->first()??AiCostBudget::whereNull('tenant_id')->where('period',now()->format('Y-m'))->first(); if(!$budget)return; $spent=(float)AiCostLedger::where('tenant_id',$tenant->id)->where('billing_period',now()->format('Y-m'))->sum('cost_usd'); if($spent >= (float)$budget->budget_usd)throw new RuntimeException('AI_COST_BUDGET_EXCEEDED'); }
 public function record(Tenant $tenant, RuntimeRun $run, array $usage): AiCostLedger {return DB::transaction(function()use($tenant,$run,$usage){$key='runtime_run:'.$run->id;if($e=AiCostLedger::where('tenant_id',$tenant->id)->where('idempotency_key',$key)->first())return$e;$rate=AiProviderRate::where('provider',$run->provider_code)->where('model',$run->model_code)->where('enabled',true)->where('effective_from','<=',now())->latest('effective_from')->first();$cost=(float)($usage['cost_usd']??0);if(!$cost&&$rate){$input=max(0,(int)($usage['input_tokens']??0)-(int)($usage['cached_input_tokens']??0));$cost=($input*(float)$rate->input_cost_per_million+(int)($usage['cached_input_tokens']??0)*(float)$rate->cached_input_cost_per_million+(int)($usage['output_tokens']??0)*(float)$rate->output_cost_per_million)/1000000;}return AiCostLedger::create(['tenant_id'=>$tenant->id,'agent_id'=>$run->agent_id,'runtime_run_id'=>$run->id,'provider'=>$run->provider_code,'model'=>$run->model_code,'input_tokens'=>(int)($usage['input_tokens']??0),'cached_input_tokens'=>(int)($usage['cached_input_tokens']??0),'output_tokens'=>(int)($usage['output_tokens']??0),'total_tokens'=>(int)($usage['total_tokens']??0),'cost_usd'=>$cost,'billing_period'=>now()->format('Y-m'),'idempotency_key'=>$key]);});}
}
